Algoritmo Notas
  Dimension notas[4] Como Entero;
  notas[0] <- 7;
  notas[1] <- 9;
  notas[2] <- 6;
  notas[3] <- 8;
  Definir suma Como Entero <- 0;
  Para i <- 0 Hasta 3 Hacer
    suma <- suma + notas[i];
  FinPara
  Escribir "Media: ", suma / 4;
FinAlgoritmo

Algoritmo Tabla
  Dimension tabla[2, 3] Como Entero;
  Para f <- 0 Hasta 1 Hacer
    Para c <- 0 Hasta 2 Hacer
      tabla[f, c] <- (f + 1) * (c + 1);
    FinPara
  FinPara
  Escribir tabla[0, 2], " ", tabla[1, 2];
FinAlgoritmo

Algoritmo Varios
  Dimension precios[3], cantidades[3] Como Entero;
  precios[0] <- 12;
  cantidades[0] <- 2;
  Escribir precios[0] * cantidades[0];
FinAlgoritmo

Algoritmo Fuera
  Dimension v[3] Como Entero;
  v[3] <- 1;
FinAlgoritmo

Algoritmo Indices
  Dimension m[2, 2] Como Entero;
  m[0] <- 1;
FinAlgoritmo

Algoritmo EscribirArreglo
  Dimension v[2] Como Entero;
  v[0] <- 1;
  v[1] <- 2;
  Escribir v;
FinAlgoritmo
